import{_ as n,o as i,c as e,a2 as a}from"./chunks/framework.O93z6AWZ.js";const u=JSON.parse('{"title":"Đề tài 3.4 — Suy tim cấp tốc","description":"","frontmatter":{"title":"Đề tài 3.4 — Suy tim cấp tốc"},"headers":[],"relativePath":"du_an/suy_tim_risk_dxai.md","filePath":"du_an/suy_tim_risk_dxai.md"}'),r={name:"du_an/suy_tim_risk_dxai.md"};function o(c,t,d,h,s,g){return i(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="đe-tai-3-4-phan-tang-nguy-co-tu-vong-suy-tim-tu-du-lieu-bang-phien-ban-cap-toc" tabindex="-1">Đề tài 3.4: Phân tầng nguy cơ tử vong Suy tim từ dữ liệu bảng (phiên bản CẤP TỐC) <a class="header-anchor" href="#đe-tai-3-4-phan-tang-nguy-co-tu-vong-suy-tim-tu-du-lieu-bang-phien-ban-cap-toc" aria-label="Permalink to &quot;Đề tài 3.4: Phân tầng nguy cơ tử vong Suy tim từ dữ liệu bảng (phiên bản CẤP TỐC)&quot;">​</a></h1><p><strong>Nhóm đề tài:</strong> 3. Bệnh án Điện tử &amp; Dữ liệu Bảng (Clinical Tabular &amp; EHR) · <strong>Trạng thái:</strong> ✅ Y văn + Workflow cấp tốc đầy đủ</p><div class="tip custom-block"><p class="custom-block-title">⚡ Đề tài dễ nhất, nhanh nhất trong toàn bộ ngân hàng đề tài</p><p>Dữ liệu thô và mã nguồn chi tiết được lưu trữ <strong>Private</strong> trên kho GitHub của bộ môn (để đảm bảo sinh viên tự thực hiện). Sinh viên tham khảo thông tin mức độ cơ bản tại đây.</p></div><p>Đọc trước <strong><a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a></strong>.</p><hr><h2 id="_1-phat-bieu-bai-toan" tabindex="-1">1. Phát biểu bài toán <a class="header-anchor" href="#_1-phat-bieu-bai-toan" aria-label="Permalink to &quot;1. Phát biểu bài toán&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Câu hỏi nghiên cứu</strong></td><td>Mô hình học máy nào dự báo tốt nhất nguy cơ tử vong ở bệnh nhân suy tim từ đặc trưng lâm sàng dạng bảng?</td></tr><tr><td><strong>Input (X)</strong></td><td>13 đặc trưng lâm sàng (tuổi, ejection fraction, serum creatinine, serum sodium...)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Nhị phân: tử vong / sống sót (DEATH_EVENT) trong thời gian theo dõi</td></tr><tr><td><strong>Dataset</strong></td><td><a href="https://archive.ics.uci.edu/dataset/519/heart+failure+clinical+records" target="_blank" rel="noreferrer">Heart Failure Clinical Records</a> (UCI/Kaggle) — 299 bệnh nhân, tải ngay, không cần xin quyền</td></tr></tbody></table><h2 id="_2-y-van-khoi-đong-3-bai-—-toi-gian-co-chu-đich" tabindex="-1">2. Y văn khởi động (3 bài — tối giản có chủ đích) <a class="header-anchor" href="#_2-y-van-khoi-đong-3-bai-—-toi-gian-co-chu-đich" aria-label="Permalink to &quot;2. Y văn khởi động (3 bài — tối giản có chủ đích)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th>Vai trò</th></tr></thead><tbody><tr><td><code>mpanya2021predicting</code> <em>(CONTEXT)</em></td><td>Tổng quan hệ thống 30 nghiên cứu ML cho suy tim</td></tr><tr><td><code>chicco2020machine</code></td><td><strong>Bài gốc</strong> — Random Forest, Accuracy 74,0%, MCC 0,384</td></tr><tr><td><code>ishaq2021improving</code></td><td><strong>Mục tiêu vượt qua</strong> — cùng dữ liệu + SMOTE, Accuracy 92,6%</td></tr></tbody></table><h2 id="_3-workflow-cap-toc-—-5-buoi-kem-code-chay-đuoc-ngay" tabindex="-1">3. Workflow cấp tốc — 5 buổi, kèm code chạy được ngay <a class="header-anchor" href="#_3-workflow-cap-toc-—-5-buoi-kem-code-chay-đuoc-ngay" aria-label="Permalink to &quot;3. Workflow cấp tốc — 5 buổi, kèm code chạy được ngay&quot;">​</a></h2><p>Xem lộ trình 5 buổi (mã nguồn và workflow chi tiết được giữ <strong>Private</strong> trên GitHub của bộ môn để đảm bảo sinh viên tự code):</p><table tabindex="0"><thead><tr><th style="text-align:center;">Buổi</th><th>Nội dung</th><th style="text-align:center;">Thời lượng</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td>EDA + Patient-level Split + Chuẩn hóa</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">2</td><td>Baseline (Logistic Regression + Random Forest)</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">3</td><td>SMOTE + Extra Trees — hướng tới mốc 92,6%</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">4</td><td>XAI bắt buộc (SHAP) — đối chiếu Serum Creatinine/Ejection Fraction</td><td style="text-align:center;">2–3h</td></tr><tr><td style="text-align:center;">5</td><td>Hoàn thiện báo cáo</td><td style="text-align:center;">2–3h</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Mọi trích dẫn phải khớp key có thật trong <code>.bib</code> đã xác minh DOI qua Crossref API.</p></div>',13)])])}const b=n(r,[["render",o]]);export{u as __pageData,b as default};
